  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore: SessionStore | undefined
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') {
    await handleListSessions(ws, session, sessionStore, {limit: message.limit, before: message.before});
  }
}

// The user comes from the authenticated session, never from the frame; the answer is metadata, no entries.
async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  options: SessionListOptions
): Promise<void> {
  try {
    const summaries = (await sessionStore?.listFor?.(session.userId, options)) ?? [];
    sendJson(ws, {
      type: 'session_list',
      sessions: summaries.map(summary => ({
        sessionId: summary.sessionId,
        createdAt: new Date(summary.createdAt).toISOString(),
        updatedAt: new Date(summary.updatedAt).toISOString(),
        entryCount: summary.entryCount,
      })),
    });
  } catch (error) {
    log.error('ws', 'session list failed', {
      sessionId: session.sessionId,
      userId: session.userId,
      error: error instanceof Error ? error.message : 'Unknown error',
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

